<?php
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';require_once dirname(__DIR__).'/includes/incentive.php';
$user=require_administrator();$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!valid_csrf()){$errors[]='The form expired. Reload and try again.';http_response_code(403);}else try{$action=post_string('action');if($action==='save'){$id=post_id('id');phase6_save_rule($pdo,$_POST,(int)$user['id'],$id);flash('success',$id?'Incentive rule was updated.':'Incentive rule was created.');}elseif($action==='status'){phase6_set_rule_active($pdo,(int)post_id('id'),post_string('active')==='1',(int)$user['id']);flash('success','Incentive rule status was updated.');}else throw new Phase6ValidationException(['Unknown rule action.']);redirect('admin/incentive-rules.php');}catch(Phase6ValidationException|Phase6ConflictException $e){$errors[]=$e->getMessage();}}
$editId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$edit=null;if($editId){$q=$pdo->prepare('SELECT * FROM incentive_rules WHERE id=?');$q->execute([$editId]);$edit=$q->fetch();}
$rules=$pdo->query('SELECT ir.*,u.full_name creator_name,(SELECT COUNT(*) FROM incentive_transactions it WHERE it.rule_id=ir.id) transaction_count FROM incentive_rules ir LEFT JOIN users u ON u.id=ir.created_by ORDER BY ir.effective_date DESC,ir.id DESC')->fetchAll();$pageTitle='Incentive Rules';$activeNav='incentives';$flash=consume_flash();require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-heading"><div><div class="breadcrumb"><a href="<?= e(url('admin/incentives.php')) ?>">Incentives</a> <span>/</span> Rules</div><h1>Configurable incentive rules</h1><p>No conversion rate is official until Barangay administrators configure and approve it.</p></div></div>
<?php if($flash): ?><div class="notice notice-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php foreach($errors as $error): ?><div class="notice notice-error"><?= e($error) ?></div><?php endforeach; ?>
<form method="post" class="panel record-form"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="panel-heading"><div><h2><?= $edit?'Edit rule':'Add rule' ?></h2><p>Overlapping active periods for the same oil unit are rejected.</p></div></div><div class="form-grid"><label class="form-field form-span"><span>Rule name</span><input name="name" maxlength="150" required value="<?= e($_POST['name']??$edit['name']??'') ?>" placeholder="Development test rule or approved policy name"></label><label class="form-field"><span>Oil threshold</span><input type="number" min="0.001" step="0.001" name="minimum_oil_quantity" required value="<?= e((string)($_POST['minimum_oil_quantity']??$edit['minimum_oil_quantity']??'')) ?>"></label><label class="form-field"><span>Oil unit</span><select name="oil_unit" required><option value="L"<?= selected($_POST['oil_unit']??$edit['oil_unit']??'L','L') ?>>L</option><option value="kg"<?= selected($_POST['oil_unit']??$edit['oil_unit']??'','kg') ?>>kg</option></select></label><label class="form-field"><span>Rice reward</span><input type="number" min="0.001" step="0.001" name="rice_reward_quantity" required value="<?= e((string)($_POST['rice_reward_quantity']??$edit['rice_reward_quantity']??'')) ?>"></label><label class="form-field"><span>Rice unit</span><select name="rice_unit" required><option value="kg"<?= selected($_POST['rice_unit']??$edit['rice_unit']??'kg','kg') ?>>kg</option><option value="g"<?= selected($_POST['rice_unit']??$edit['rice_unit']??'','g') ?>>g</option></select></label><label class="form-field"><span>Calculation</span><select name="calculation_type"><option value="FIXED_PER_THRESHOLD"<?= selected($_POST['calculation_type']??$edit['calculation_type']??'FIXED_PER_THRESHOLD','FIXED_PER_THRESHOLD') ?>>Floor per complete threshold block</option><option value="FIXED_TRANSACTION"<?= selected($_POST['calculation_type']??$edit['calculation_type']??'','FIXED_TRANSACTION') ?>>One fixed reward per qualifying transaction</option></select></label><label class="form-field"><span>Effective from</span><input type="date" name="effective_date" required value="<?= e($_POST['effective_date']??$edit['effective_date']??date('Y-m-d')) ?>"></label><label class="form-field"><span>Effective until</span><input type="date" name="end_date" value="<?= e($_POST['end_date']??$edit['end_date']??'') ?>"></label><label class="check-field"><input type="checkbox" name="is_active" value="1"<?= !isset($_POST['action'])?((!$edit||(bool)$edit['is_active'])?' checked':''):(!empty($_POST['is_active'])?' checked':'') ?>> Active</label><label class="check-field"><input type="checkbox" name="is_test" value="1"<?= !isset($_POST['action'])?(!empty($edit['is_test'])?' checked':''):(!empty($_POST['is_test'])?' checked':'') ?>> DEVELOPMENT / TEST DATA</label></div><div class="form-actions"><?php if($edit): ?><a class="button button-secondary" href="<?= e(url('admin/incentive-rules.php')) ?>">Cancel</a><?php endif; ?><button class="button button-primary" type="submit">Save rule</button></div></form>
<section class="panel section-panel"><div class="panel-heading"><div><h2>Rule history</h2><p>Transactions retain snapshots when these definitions later change.</p></div></div><div class="table-scroll"><table><thead><tr><th>Rule</th><th>Oil threshold</th><th>Reward</th><th>Calculation</th><th>Effective period</th><th>Status</th><th>Use</th><th>Action</th></tr></thead><tbody><?php foreach($rules as $rule): ?><tr><td><?= e($rule['name']) ?><?= $rule['is_test']?' · TEST DATA':'' ?></td><td><?= e(number_format((float)$rule['minimum_oil_quantity'],3).' '.$rule['oil_unit']) ?></td><td><?= e(number_format((float)$rule['rice_reward_quantity'],3).' '.$rule['rice_unit']) ?></td><td><?= e(str_replace('_',' ',$rule['calculation_type'])) ?></td><td><?= e($rule['effective_date'].' to '.($rule['end_date']??'open-ended')) ?></td><td><?= $rule['is_active']?'ACTIVE':'INACTIVE' ?></td><td><?= (int)$rule['transaction_count'] ?> transactions</td><td><a class="table-action" href="<?= e(url('admin/incentive-rules.php?id='.(int)$rule['id'])) ?>">Edit</a><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$rule['id'] ?>"><input type="hidden" name="active" value="<?= $rule['is_active']?'0':'1' ?>"><button class="table-action button-link" type="submit"><?= $rule['is_active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?><?php if(!$rules): ?><tr><td colspan="8" class="empty-state">No rule exists. Configure one before processing approved surrenders.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
